// The FactorIA program icon, embedded in the editor (tools/editor/icon/, regenerated by make_icons.py): the window icon on
// Windows and Linux and the Dock icon on macOS, where the editor is the `factoria` executable rather than an app bundle.
// And the program's name the Dock shows on macOS for the same reason.
#pragma once

#include <vector>

#include "fa/platform/app.h"

namespace fa::editor {

// The window icon in every embedded size (16..256, smallest first; the 16 and 24 px ones are a simplified drawing).
std::vector<AppIconImage> editor_window_icon();
// The Dock icon (512 px, on Apple's icon grid). Empty if it could not be decoded.
AppIconImage editor_dock_icon();
// macOS: the name the Dock (its tooltip, Cmd+Tab, Force Quit) shows for this process, instead of the executable's name
// (`factoria`). Call it once NSApp exists (from AppDesc::init on). false: not available (other platforms: Windows takes
// the name from the exe's version resource, Linux from AppDesc::appName).
bool set_dock_name(const char* name);

}  // namespace fa::editor
